// --- src/shared.js ---
function toArray(value) {
  return Array.isArray(value) ? value : [];
}

function normalizeQuery(raw) {
  return String(raw || "");
}

function normalizeCount(raw) {
  return Math.max(1, Math.min(Number(raw || 5), 20));
}

function dedupeHits(hits) {
  var out = [];
  var seen = Object.create(null);
  for (var i = 0; i < hits.length; i += 1) {
    var hit = hits[i];
    if (!hit || !hit.url || seen[hit.url]) {
      continue;
    }
    seen[hit.url] = true;
    out.push(hit);
  }
  return out;
}

function sentinelResponse(backend, warning) {
  return {
    backend: backend,
    hits: [],
    warnings: [warning]
  };
}

function missingKeyWarning(secretName) {
  return "__missing_key__:" + String(secretName || "");
}

function unauthorizedWarning(status) {
  return "__unauthorized__:" + String(status || 401);
}

function isUnauthorizedStatus(status) {
  return status === 401 || status === 403;
}

function extractSecretName(err, fallback) {
  if (err && err.details && err.details.secretName) {
    return String(err.details.secretName);
  }
  return fallback;
}

function parseJsonBody(raw, backend) {
  var text = raw == null ? "" : String(raw);
  if (!text) {
    return {};
  }
  try {
    return JSON.parse(text);
  } catch (err) {
    throw new Error("web_search backend `" + backend + "` returned invalid JSON");
  }
}

async function fetchJsonBackend(backend, req, options) {
  try {
    var response = await tomcat.fetch(options.request);
    if (response && response.data && typeof response.data.status === "number") {
      response = response.data;
    }
    if (isUnauthorizedStatus(response && response.status)) {
      return sentinelResponse(backend, unauthorizedWarning(response.status));
    }
    if (!response || typeof response.status !== "number") {
      throw new Error(
        "web_search backend `" + backend + "` returned an invalid HTTP envelope"
      );
    }
    if (response.status < 200 || response.status >= 300) {
      var detail;
      try {
        var payload = JSON.parse(response.body);
        if (payload && payload.error && typeof payload.error.message === "string") {
          detail = payload.error.message.replace(/[\r\n]+/g, " ").slice(0, 512);
        }
      } catch (_) { /* Non-JSON errors retain the HTTP status. */ }
      var message = (options.statusMessages && options.statusMessages[response.status]) ||
        "web_search backend `" + backend + "` returned HTTP status " + response.status;
      throw new Error(detail ? message + ": " + detail : message);
    }
    return {
      backend: backend,
      hits: dedupeHits(options.parse(parseJsonBody(response.body, backend))),
      warnings: options.warnings || []
    };
  } catch (err) {
    if (err && err.code === "missing_secret") {
      return {
        backend: backend,
        hits: [],
        warnings: (options.warnings || []).concat([
          missingKeyWarning(extractSecretName(err, options.secretName))
        ])
      };
    }
    throw err;
  }
}

function rewriteQueryWithDomainFilter(query, domains) {
  if (!domains || !domains.length) {
    return query;
  }
  var filters = [];
  for (var i = 0; i < domains.length; i += 1) {
    filters.push("site:" + domains[i]);
  }
  return "(" + query + ") (" + filters.join(" OR ") + ")";
}

function buildWebSearchTool(req) {
  var tool = {
    type: "web_search",
    force_search: true,
    limit: normalizeCount(req.count),
    max_keyword: 3
  };

  if (req.domainFilter && req.domainFilter.length) {
    tool.filters = {
      allowed_domains: req.domainFilter.slice()
    };
  }

  if (req.country) {
    tool.user_location = {
      type: "approximate",
      country: String(req.country).toUpperCase()
    };
  }

  return tool;
}

function collectAnnotations(message) {
  var annotations = [];
  if (message && Array.isArray(message.annotations)) {
    annotations = annotations.concat(message.annotations);
  }
  if (message && Array.isArray(message.content)) {
    for (var i = 0; i < message.content.length; i += 1) {
      var part = message.content[i];
      if (part && Array.isArray(part.annotations)) {
        annotations = annotations.concat(part.annotations);
      }
    }
  }
  return annotations;
}

function annotationToHit(annotation) {
  if (!annotation || annotation.type !== "url_citation" || !annotation.url) {
    return null;
  }
  return {
    title: annotation.title || null,
    url: String(annotation.url),
    snippet: annotation.summary || annotation.snippet || null,
    published_at: annotation.publish_time || annotation.published_at || null
  };
}

// --- src/parsers.js ---
function parseTavilyResponse(body) {
  var results = toArray(body && body.results);
  var hits = [];
  for (var i = 0; i < results.length; i += 1) {
    var item = results[i];
    if (!item || !item.url) {
      continue;
    }
    hits.push({
      title: item.title || null,
      url: String(item.url),
      snippet: item.content || item.snippet || null,
      published_at: item.published_date || item.published_at || null
    });
  }
  return hits;
}

function parseBraveResponse(body) {
  var results = toArray(body && body.web && body.web.results);
  var hits = [];
  for (var i = 0; i < results.length; i += 1) {
    var item = results[i];
    if (!item || !item.url) {
      continue;
    }
    hits.push({
      title: item.title || null,
      url: String(item.url),
      snippet: item.description || item.snippet || null,
      published_at: item.age || item.page_age || null
    });
  }
  return hits;
}

function parseSerperResponse(body) {
  var results = toArray(body && body.organic);
  var hits = [];
  for (var i = 0; i < results.length; i += 1) {
    var item = results[i];
    if (!item || !item.link) {
      continue;
    }
    hits.push({
      title: item.title || null,
      url: String(item.link),
      snippet: item.snippet || null,
      published_at: item.date || null
    });
  }
  return hits;
}

function tavilyTimeRange(freshness) {
  return freshness ? String(freshness) : null;
}

function braveFreshness(freshness) {
  if (freshness === "day") return "pd";
  if (freshness === "week") return "pw";
  if (freshness === "month") return "pm";
  if (freshness === "year") return "py";
  return null;
}

function serperFreshness(freshness) {
  if (freshness === "day") return "qdr:d";
  if (freshness === "week") return "qdr:w";
  if (freshness === "month") return "qdr:m";
  if (freshness === "year") return "qdr:y";
  return null;
}

// --- src/backends/brave.js ---
async function searchWithBrave(req) {
  var warnings = [];
  var query = normalizeQuery(req.query);
  if (req.domainFilter && req.domainFilter.length) {
    query = rewriteQueryWithDomainFilter(query, req.domainFilter);
    warnings.push("brave_domain_filter_via_query_rewrite");
  }
  var queryParams = {
    q: query,
    count: normalizeCount(req.count)
  };
  if (req.country) {
    queryParams.country = String(req.country);
  }
  if (req.language) {
    queryParams.search_lang = String(req.language);
  }
  if (req.freshness) {
    var mappedFreshness = braveFreshness(req.freshness);
    if (mappedFreshness) {
      queryParams.freshness = mappedFreshness;
    }
  }
  return fetchJsonBackend("brave", req, {
    secretName: "BRAVE_API_KEY",
    warnings: warnings,
    request: {
      method: "GET",
      url: BRAVE_BASE_URL + "/res/v1/web/search",
      headers: {
        Accept: "application/json",
        "X-Subscription-Token": "{{secret:BRAVE_API_KEY}}"
      },
      query: queryParams
    },
    parse: parseBraveResponse
  });
}

// --- src/backends/deepseek.js ---
function deepseekAfterDate(freshness) {
  var days = { day: 1, week: 7, month: 30, year: 365 }[freshness];
  if (!days) return null;
  return new Date(Date.now() - days * 86400000).toISOString().slice(0, 10);
}

function parseDeepSeekResponse(body) {
  if (!body || !Array.isArray(body.results)) {
    throw new Error("DeepSeek search response is missing a results array");
  }
  return body.results.filter(function (item) {
    return item && typeof item.url === "string" && item.url.trim();
  }).map(function (item) {
    var snippet = typeof item.snippet === "string" ? item.snippet : "";
    var summary = typeof item.summary === "string" ? item.summary : "";
    return {
      title: typeof item.title === "string" && item.title.trim() ? item.title : item.url,
      url: item.url,
      snippet: snippet || summary || null,
      published_at: typeof item.date === "string" ? item.date : null
    };
  });
}

async function searchWithDeepSeek(req) {
  var warnings = req.country ? ["deepseek_ignores_country"] : [];
  var query = normalizeQuery(req.query).trim();
  if (query) {
    query = rewriteQueryWithDomainFilter(query, req.domainFilter);
    if (req.language) query += " lang:" + req.language;
    var after = deepseekAfterDate(req.freshness);
    if (after) query += " after:" + after;
  }
  if (!query || Array.from(query).length > 128) {
    return {
      backend: "deepseek",
      hits: [],
      warnings: warnings.concat([query ? "deepseek_query_too_long" : "deepseek_query_empty"]),
      unsupported_backend: true
    };
  }
  return fetchJsonBackend("deepseek", req, {
    secretName: "DEEPSEEK_API_KEY",
    warnings: warnings,
    statusMessages: { 402: "DeepSeek search: insufficient balance (HTTP 402)" },
    request: {
      method: "POST",
      url: "https://api.deepseek.com/v1/tools/search",
      headers: {
        Authorization: "Bearer {{secret:DEEPSEEK_API_KEY}}",
        "Content-Type": "application/json"
      },
      body: { query: query, count: normalizeCount(req.count), need_content: false }
    },
    parse: parseDeepSeekResponse
  });
}

// --- src/backends/mimo.js ---
async function searchWithMimo(req) {
  if (typeof req.model !== "string" || !req.model) {
    return { backend: "mimo", hits: [], warnings: ["mimo_requires_model"], unsupported_backend: true };
  }
  var warnings = [];
  if (req.language) {
    warnings.push("mimo_ignores_language");
  }

  var response = await tomcat.createChatCompletion({
    model: req.model,
    messages: [
      {
        role: "user",
        content: normalizeQuery(req.query)
      }
    ],
    tools: [buildWebSearchTool(req)]
  });

  var choice = response && response.choices && response.choices[0] ? response.choices[0] : null;
  var message = choice && choice.message ? choice.message : {};
  var annotations = collectAnnotations(message);
  var hits = [];

  for (var i = 0; i < annotations.length; i += 1) {
    var hit = annotationToHit(annotations[i]);
    if (hit) {
      hits.push(hit);
    }
  }

  return {
    backend: "mimo",
    hits: dedupeHits(hits),
    warnings: warnings
  };
}

// --- src/backends/openai.js ---
var OPENAI_SEARCH_MODEL = "gpt-6.2-sol";

function parseOpenAISearch(body) {
  if (!body || !Array.isArray(body.output) || body.error) {
    throw new Error((body && body.error && body.error.message) || "OpenAI web search returned no output");
  }
  var complete = body.status === undefined || body.status === "completed";
  var hits = [];
  var sources = [];
  for (var item of body.output) {
    if (!item) continue;
    if (item.type === "message") {
      for (var part of toArray(item.content)) {
        if (!part || part.type !== "output_text") continue;
        var chars = Array.from(part.text || "");
        for (var annotation of collectAnnotations(part)) {
          var hit = annotationToHit(annotation);
          if (!hit) continue;
          var start = annotation.start_index;
          var end = annotation.end_index;
          if (Number.isInteger(start) && Number.isInteger(end) && start >= 0 && start < end && end <= chars.length) {
            hit.snippet = chars.slice(start, end).join("");
          }
          hits.push(hit);
        }
      }
    } else if (item.type === "web_search_call") {
      if (item.status === "failed" || item.status === "incomplete") complete = false;
      for (var source of toArray(item.action && item.action.sources)) {
        if (source && typeof source.url === "string") {
          sources.push({ url: source.url, title: source.title || null, snippet: source.snippet || null });
        }
      }
    }
  }
  // Partial output still carries usable links; an empty unfinished one must let routing continue.
  hits = hits.concat(sources);
  if (!hits.length && !complete) {
    throw new Error("OpenAI web search did not complete");
  }
  return hits;
}

async function searchWithOpenAI(req) {
  var tool = { type: "web_search", search_context_size: "medium" };
  var domains = toArray(req.domainFilter);
  if (domains.length) tool.filters = { allowed_domains: domains.slice() };
  if (req.country) tool.user_location = { type: "approximate", country: String(req.country).toUpperCase() };
  return fetchJsonBackend("openai", req, {
    request: {
      url: "https://api.openai.com/v1/responses",
      method: "POST",
      headers: { Authorization: "Bearer {{host_key}}", "Content-Type": "application/json" },
      body: {
        model: OPENAI_SEARCH_MODEL,
        input: normalizeQuery(req.query),
        store: false,
        tool_choice: "required",
        include: ["web_search_call.action.sources"],
        tools: [tool]
      }
    },
    parse: parseOpenAISearch
  });
}

// --- src/backends/serper.js ---
async function searchWithSerper(req) {
  var warnings = [];
  var query = normalizeQuery(req.query);
  if (req.domainFilter && req.domainFilter.length) {
    query = rewriteQueryWithDomainFilter(query, req.domainFilter);
    warnings.push("serper_domain_filter_via_query_rewrite");
  }
  var body = {
    q: query,
    num: normalizeCount(req.count)
  };
  if (req.country) {
    body.gl = String(req.country);
  }
  if (req.language) {
    body.hl = String(req.language);
  }
  if (req.freshness) {
    var mappedFreshness = serperFreshness(req.freshness);
    if (mappedFreshness) {
      body.tbs = mappedFreshness;
    }
  }
  return fetchJsonBackend("serper", req, {
    secretName: "SERPER_API_KEY",
    warnings: warnings,
    request: {
      method: "POST",
      url: SERPER_BASE_URL + "/search",
      headers: {
        "Content-Type": "application/json",
        "X-API-KEY": "{{secret:SERPER_API_KEY}}"
      },
      body: body
    },
    parse: parseSerperResponse
  });
}

// --- src/backends/tavily.js ---
async function searchWithTavily(req) {
  var warnings = [];
  if (req.country || req.language) {
    warnings.push("tavily_ignores_country_language");
  }
  var body = {
    query: normalizeQuery(req.query),
    max_results: normalizeCount(req.count)
  };
  if (req.freshness) {
    body.time_range = tavilyTimeRange(req.freshness);
  }
  if (req.domainFilter && req.domainFilter.length) {
    body.include_domains = req.domainFilter.slice();
  }
  return fetchJsonBackend("tavily", req, {
    secretName: "TAVILY_API_KEY",
    warnings: warnings,
    request: {
      method: "POST",
      url: TAVILY_BASE_URL + "/search",
      headers: {
        Authorization: "Bearer {{secret:TAVILY_API_KEY}}",
        "Content-Type": "application/json"
      },
      body: body
    },
    parse: parseTavilyResponse
  });
}

// --- src/index.js ---
var backends = Object.assign(Object.create(null), {
  mimo: searchWithMimo,
  tavily: searchWithTavily,
  brave: searchWithBrave,
  serper: searchWithSerper,
  deepseek: searchWithDeepSeek,
  openai: searchWithOpenAI
});

async function dispatchBackend(req) {
  var backend = req.backend;
  if (typeof backends[backend] !== "function") {
    return { backend: backend, hits: [], warnings: [], unsupported_backend: true };
  }
  return backends[backend](req);
}

tomcat.registerFunction("webSearchBackend", async function (params) {
  return dispatchBackend(params || {});
});
